#!/bin/sh
# Generated by nocturne/build from nocturne/palette.toml. Edit that file, not this one.
# The login screen. greetd runs this (see system/etc/greetd/config.toml).
# `nocturne greeter install` puts it in /usr/local/bin.
#
# First choice: the Nocturne login screen, greeter/shell.qml, drawn by
# Quickshell inside labwc, a small compositor. labwc is there for that one
# window and for the touchpad (tap to click); greeter/rc.xml is its config.
# If the screen logs you in, this script is done. If it is not installed, or
# stops with an error, the text login below takes over, so a broken login
# screen never locks you out.
screen=/etc/greetd/nocturne
if [ -f "$screen/shell.qml" ] && command -v labwc >/dev/null 2>&1 && command -v qs >/dev/null 2>&1; then
    # The greeter's user has no home folder, and Quickshell wants somewhere
    # to keep its cache.
    export XDG_CACHE_HOME="${XDG_RUNTIME_DIR:-/tmp}/nocturne-greeter-cache"
    export QT_QPA_PLATFORM=wayland

    # The console underneath shows for a moment after login, before Hyprland
    # draws. Leave it empty and in Hyprland's own background colour: wipe
    # what the boot left there, hide the cursor, and send what labwc and
    # Quickshell print to the journal (journalctl -t nocturne-greeter).
    if [ "${TERM:-linux}" = linux ]; then
        printf '\033]P0080b14\033[2J\033[H\033[?25l'
    fi

    # -S runs the screen and ends labwc when the screen ends. First
    # outputs.sh gives each display its desktop scale. labwc does not pass on
    # how the screen ended, so its exit code is left in a file.
    # labwc starts the command without a shell, hence the sh -c.
    status="${XDG_RUNTIME_DIR:-/tmp}/nocturne-greeter.status"
    rm -f "$status"
    systemd-cat -t nocturne-greeter labwc -C "$screen" \
        -S "sh -c 'sh $screen/outputs.sh; qs -p $screen; echo \$? >$status'"
    if [ "$(cat "$status" 2>/dev/null)" = 0 ]; then
        exit 0
    fi

    if [ "${TERM:-linux}" = linux ]; then
        printf '\033[?25h'
    fi
fi

# Fallback: tuigreet on the bare console.
# The Linux console has sixteen colours and no more, so this sets them from
# the palette and then names them in tuigreet's theme. ESC ] P <slot> <rrggbb>
# changes one colour for this console only; other consoles keep their own.
# The slots are chosen for the login screen, not for a shell:
#   black     ink-0   the screen and the form
#   darkgray  line    the hairline around the form
#   gray      text    what you type
#   lightblue muted   labels and the date
#   lightcyan faint   key hints
#   magenta   accent  the password, like the dots on the lock screen
#   white     bright
if [ "${TERM:-linux}" = linux ]; then
    printf '\033]P0080b14\033]P1fc5950\033]P27dd89f\033]P3f2c36a'
    printf '\033]P48ab6f7\033]P5f4a4ad\033]P68bd6de\033]P7d9deec'
    printf '\033]P830364a\033]P9ff7f73\033]PA91ecb2\033]PBffd891'
    printf '\033]PCa1a7bb\033]PDffbdc4\033]PE80879d\033]PFf3f5fc'
    # Repaint the screen in the new background.
    printf '\033[2J\033[H'
fi

# The same session the login screen starts, when it is installed.
session=start-hyprland
if [ -f "$screen/session.sh" ]; then
    session="sh $screen/session.sh"
fi

# F3 lists the other sessions; X11 ones start through startx.
exec tuigreet \
    --cmd "$session" \
    --sessions /usr/share/wayland-sessions \
    --xsessions /usr/share/xsessions \
    --remember \
    --asterisks \
    --time --time-format '%a %-d %b  %H:%M' \
    --theme 'container=black;border=darkgray;text=gray;prompt=lightblue;time=lightblue;greet=lightblue;title=lightblue;action=lightcyan;button=lightcyan;input=magenta' \
    --power-shutdown 'sudo systemctl poweroff'
